  (base : (x y : ℕ) → ¬(0 < y ∧ y ≤ x) → motive x y) : motive x y

def Nat.div.inductionOn.{u} {motive : ℕ → ℕ → Sort u} (x y : ℕ)
  (ind : (x y : ℕ) → 0 < y ∧ y ≤ x → motive (x - y) y → motive x y)
  (base : (x y : ℕ) → ¬(0 < y ∧ y ≤ x) → motive x y) : motive x y

theorem Nat.bitwise.eq_def✝ (f : Bool → Bool → Bool) (n m : ℕ) :
  Nat.bitwise f n m =
    if n = 0 then if f false true = true then m else 0
    else
      if m = 0 then if f true false = true then n else 0
      else
        have n' := n / 2;
        have m' := m / 2;
        let b₁ := n % 2 = 1;
        let b₂ := m % 2 = 1;
        have r := Nat.bitwise f n' m';
        if f (decide b₁) (decide b₂) = true then r + r + 1 else r + r
